import os
import tomllib
from typing import Any


class EnvCfgError(Exception):
    pass


def _coerce_int(s: str) -> int:
    return int(s)


def _coerce_float(s: str) -> float:
    return float(s)


def _coerce_bool(s: str) -> bool:
    lower = s.lower()
    if lower in ("true", "yes", "1"):
        return True
    if lower in ("false", "no", "0"):
        return False
    raise ValueError("invalid bool")


def _coerce(s: str, target: type) -> Any:
    if target is int:
        return _coerce_int(s)
    if target is float:
        return _coerce_float(s)
    if target is bool:
        return _coerce_bool(s)
    if target is str:
        return s
    raise ValueError(f"unsupported type {target}")


def load_config(
    defaults: dict[str, Any],
    toml_path: str | None = None,
    env_prefix: str = "APP",
    env: dict[str, str] | None = None,
) -> dict[str, Any]:
    cfg = dict(defaults)

    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                cfg = {**cfg, **tomllib.load(f)}
        except FileNotFoundError:
            pass

    if env is None:
        env = dict(os.environ)

    for k, v in env.items():
        if not k.startswith(env_prefix + "__"):
            continue
        path = k[len(env_prefix) + 2:].split("__")
        node = cfg
        for seg in path[:-1]:
            if seg not in node:
                node[seg] = {}
            node = node[seg]
        key = path[-1]
        if key not in node:
            raise EnvCfgError(f"env var {k} has no default")
        expected = type(node[key])
        try:
            node[key] = _coerce(v, expected)
        except ValueError as e:
            raise EnvCfgError(f"env var {k} cannot be coerced to {expected.__name__}: {e}") from e

    return cfg

