from envcfg import load_config, EnvCfgError


def test_defaults_only():
    cfg = load_config({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    cfg = load_config({"a": 1, "b": 2}, toml_path="test.toml")
    assert cfg == {"a": 1, "b": 2, "c": 3}


def test_env_overrides_toml():
    cfg = load_config({"a": 1, "b": 2}, toml_path="test.toml", env_prefix="APP")
    assert cfg == {"a": 1, "b": 2, "c": 3, "d": 4}


def test_nested_env():
    cfg = load_config({"server": {"port": 80}}, env_prefix="APP")
    assert cfg == {"server": {"port": 80}}


def test_coerce_int():
    cfg = load_config({"a": 0}, env={"APP__A": "42"})
    assert cfg == {"a": 42}


def test_coerce_float():
    cfg = load_config({"a": 0.0}, env={"APP__A": "3.14"})
    assert cfg == {"a": 3.14}


def test_coerce_bool():
    cfg = load_config({"a": False}, env={"APP__A": "yes"})
    assert cfg == {"a": True}


def test_coerce_bool_no():
    cfg = load_config({"a": True}, env={"APP__A": "no"})
    assert cfg == {"a": False}


def test_coerce_bool_one_zero():
    cfg = load_config({"a": False}, env={"APP__A": "1"})
    assert cfg == {"a": True}


def test_coerce_bool_zero():
    cfg = load_config({"a": True}, env={"APP__A": "0"})
    assert cfg == {"a": False}


def test_coerce_str():
    cfg = load_config({"a": "hello"}, env={"APP__A": "world"})
    assert cfg == {"a": "world"}


def test_coerce_int_failure():
    with pytest.raises(EnvCfgError):
        load_config({"a": 0}, env={"APP__A": "notanumber"})


def test_coerce_float_failure():
    with pytest.raises(EnvCfgError):
